<script setup>
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, reactive, ref, watch } from 'vue';

const props = defineProps({ reports: Object, filters: Object, counts: Object, pageSizes: Array, enforcementActions: Array });
const flash = computed(() => usePage().props.flash?.success);
const filter = reactive({ ...props.filters });
const reviewing = ref(null);
const decisionForm = useForm({ resolution: 'confirmed', enforcement_action: 'warning', note: '' });
const reasons = { fake_profile: 'Sahte profil', harassment: 'Taciz veya zorbalık', fraud: 'Dolandırıcılık şüphesi', spam: 'Spam', inappropriate: 'Uygunsuz profil', other: 'Diğer' };
const statuses = { pending: 'İncelenecek', confirmed: 'İhlal doğrulandı', dismissed: 'Reddedildi' };
const statusClasses = { pending: 'bg-amber-50 text-amber-900', confirmed: 'bg-red-50 text-red-800', dismissed: 'bg-slate-100 text-slate-700' };
const resolutionNotes = {
  dismissed: 'Kullanıcı profili ve bildirime konu bilgiler incelendi. Mevcut kanıtlar platform kuralı ihlalini doğrulamak için yeterli bulunmadığından bildirim reddedildi.',
  pending: 'Yeni bilgi veya ek inceleme gereksinimi nedeniyle kullanıcı bildirimi yeniden inceleme sırasına alındı. Bu bildirime bağlı önceki yaptırım kaldırıldı.',
};
const enforcementNotes = {
  record_only: 'Kullanıcı profili, hesap geçmişi ve bildirime konu bilgiler incelendi. İhlal doğrulandı ve karar denetim amacıyla kayıt altına alındı; kullanıcıya ek yaptırım uygulanmadı.',
  warning: 'Kullanıcı profili ve bildirime konu bilgiler incelendi. Platform kuralı ihlali doğrulandığından kullanıcı resmi olarak uyarıldı.',
  message_restriction_24h: 'Kullanıcıya ilişkin bildirim ve hesap hareketleri incelendi. Mesajlaşma kurallarının ihlal edildiği doğrulandığından mesaj gönderme yetkisi 24 saat kısıtlandı.',
  message_restriction_7d: 'Tekrarlanan veya ciddi mesajlaşma ihlali doğrulandığından kullanıcının mesaj gönderme yetkisi 7 gün kısıtlandı.',
  message_restriction_30d: 'Süregelen ve ciddi mesajlaşma ihlalleri doğrulandığından kullanıcının mesaj gönderme yetkisi 30 gün kısıtlandı.',
  account_suspension_24h: 'Kullanıcı bildirimi ve hesap hareketleri incelendi. Platform güvenliğini etkileyen ihlal doğrulandığından hesap 24 saat askıya alındı.',
  account_suspension_7d: 'Ciddi veya tekrarlanan platform ihlalleri doğrulandığından kullanıcı hesabı 7 gün askıya alındı.',
  account_suspension_30d: 'Süregelen ve ciddi platform ihlalleri doğrulandığından kullanıcı hesabı 30 gün askıya alındı.',
  account_suspension_indefinite: 'Platform güvenliğini veya kullanıcı topluluğunu ciddi biçimde etkileyen ihlaller doğrulandığından hesap süresiz askıya alındı.',
};
const enforcementLabels = Object.fromEntries(props.enforcementActions.map(action => [action.value, action.label]));
const refreshDecisionNote = () => {
  decisionForm.note = decisionForm.resolution === 'confirmed'
    ? enforcementNotes[decisionForm.enforcement_action]
    : resolutionNotes[decisionForm.resolution];
};
const applyFilters = () => router.get('/admin/user-reports', { ...filter, search: filter.search || undefined, status: filter.status || undefined, reason: filter.reason || undefined }, { preserveState: true, replace: true });
const setStatus = status => { filter.status = status; applyFilters(); };
const clearFilters = () => { Object.assign(filter, { search: '', status: '', reason: '', per_page: 50 }); applyFilters(); };
const openReview = report => {
  reviewing.value = report;
  decisionForm.reset();
  decisionForm.clearErrors();
  decisionForm.resolution = report.status === 'pending' ? 'confirmed' : report.status;
  decisionForm.enforcement_action = report.enforcement_action || 'warning';
  decisionForm.note = report.resolution_note || (decisionForm.resolution === 'confirmed' ? enforcementNotes[decisionForm.enforcement_action] : resolutionNotes[decisionForm.resolution]);
};
watch(() => decisionForm.resolution, () => { if (reviewing.value) refreshDecisionNote(); });
watch(() => decisionForm.enforcement_action, () => { if (reviewing.value && decisionForm.resolution === 'confirmed') refreshDecisionNote(); });
const closeReview = () => { if (!decisionForm.processing) reviewing.value = null; };
const saveDecision = () => decisionForm.patch(`/admin/user-reports/${reviewing.value.id}`, { preserveScroll: true, onSuccess: closeReview });
</script>

<template>
  <Head title="Kullanıcı Bildirimleri" />
  <AdminLayout eyebrow="Güvenlik" title="Bildirilen kullanıcılar" description="Hesap bildirimlerini kullanıcı geçmişiyle birlikte incele ve kararını denetlenebilir biçimde kaydet.">
    <main class="mx-auto max-w-[1600px] px-5 py-8 lg:px-8">
      <div v-if="flash" class="mb-5 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-900">{{ flash }}</div>
      <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><button v-for="item in [['', 'Tüm bildirimler', counts.all], ['pending', 'İncelenecek', counts.pending], ['confirmed', 'Doğrulandı', counts.confirmed], ['dismissed', 'Reddedildi', counts.dismissed]]" :key="item[0]" type="button" @click="setStatus(item[0])" :class="['rounded-2xl border bg-white p-5 text-left transition', (filter.status || '') === item[0] ? 'border-emerald-500 ring-2 ring-emerald-100' : 'border-slate-200 hover:border-slate-300']"><p class="text-sm font-semibold text-slate-700">{{ item[1] }}</p><p class="mt-2 text-3xl font-semibold text-slate-950">{{ Number(item[2]).toLocaleString('tr-TR') }}</p></button></section>
      <section class="mt-5 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><form class="grid gap-3 xl:grid-cols-[1fr_210px_210px_140px_auto]" @submit.prevent="applyFilters"><label class="text-xs font-semibold text-slate-700">Kullanıcı veya bildiren ara<input v-model="filter.search" maxlength="120" class="mt-1.5 h-11 w-full rounded-xl border border-slate-300 px-3 text-sm outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100" placeholder="Numara, ad veya e-posta" /></label><label class="text-xs font-semibold text-slate-700">Durum<select v-model="filter.status" class="mt-1.5 h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm"><option value="">Tümü</option><option v-for="(label, value) in statuses" :key="value" :value="value">{{ label }}</option></select></label><label class="text-xs font-semibold text-slate-700">Bildirim nedeni<select v-model="filter.reason" class="mt-1.5 h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm"><option value="">Tümü</option><option v-for="(label, value) in reasons" :key="value" :value="value">{{ label }}</option></select></label><label class="text-xs font-semibold text-slate-700">Sayfa başına<select v-model.number="filter.per_page" class="mt-1.5 h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm"><option v-for="size in pageSizes" :key="size" :value="size">{{ size }}</option></select></label><div class="flex items-end gap-2"><button class="h-11 rounded-xl bg-forest-700 px-5 text-sm font-semibold text-white">Uygula</button><button type="button" class="h-11 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-700" @click="clearFilters">Temizle</button></div></form></section>
      <section class="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><h2 class="text-lg font-semibold text-slate-950">Kullanıcı bildirimi kayıtları</h2><p class="mt-1 text-sm text-slate-600">{{ reports.total.toLocaleString('tr-TR') }} sonuç</p></div><p class="text-sm text-slate-600">Sayfa {{ reports.current_page }} / {{ reports.last_page }}</p></div><div v-if="reports.data.length" class="overflow-x-auto"><table class="w-full min-w-[1180px] text-left text-sm"><thead class="border-b border-slate-200 bg-slate-50 text-xs font-semibold uppercase tracking-wide text-slate-700"><tr><th class="px-5 py-3.5">Bildirim</th><th class="px-5 py-3.5">Bildirilen kullanıcı</th><th class="px-5 py-3.5">Bildiren</th><th class="px-5 py-3.5">Neden</th><th class="px-5 py-3.5">Hesap özeti</th><th class="px-5 py-3.5">Durum</th><th class="px-5 py-3.5 text-right">İşlem</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="report in reports.data" :key="report.id" class="text-slate-800 hover:bg-slate-50"><td class="px-5 py-4"><p class="font-semibold text-slate-950">#{{ report.id }}</p><p class="mt-1 text-xs text-slate-600">{{ $adminDate(report.created_at) }}</p></td><td class="px-5 py-4"><p class="font-semibold text-slate-950">{{ report.reported_user?.name || 'Kullanıcı mevcut değil' }}</p><p class="mt-0.5 text-xs text-slate-600">{{ report.reported_user?.email }}</p></td><td class="px-5 py-4"><p class="font-semibold text-slate-950">{{ report.reporter.name }}</p><p class="mt-0.5 text-xs text-slate-600">{{ report.reporter.email }}</p></td><td class="px-5 py-4 font-medium text-red-700">{{ reasons[report.reason] }}</td><td class="px-5 py-4"><p class="font-semibold text-slate-950">{{ report.reported_user?.completed_transactions || 0 }} teslimat</p><p class="mt-0.5 text-xs text-slate-600">{{ report.reported_user?.rating_count || 0 }} değerlendirme</p></td><td class="px-5 py-4"><span :class="['rounded-full px-2.5 py-1 text-xs font-semibold', statusClasses[report.status]]">{{ statuses[report.status] }}</span><p v-if="report.enforcement_action" class="mt-2 text-xs font-medium text-slate-600">{{ enforcementLabels[report.enforcement_action] }}</p></td><td class="px-5 py-4 text-right"><button type="button" title="Bildirimi incele" aria-label="Bildirimi incele" class="inline-grid size-9 place-items-center rounded-lg border border-slate-300 text-slate-700 hover:border-emerald-500 hover:text-emerald-700" @click="openReview(report)"><svg viewBox="0 0 24 24" class="size-4" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg></button></td></tr></tbody></table></div><div v-else class="px-5 py-16 text-center"><p class="font-semibold text-slate-900">Bu filtrelerde kullanıcı bildirimi bulunamadı.</p><button type="button" class="mt-3 text-sm font-semibold text-emerald-700" @click="clearFilters">Filtreleri temizle</button></div></section>
      <nav v-if="reports.last_page > 1" class="mt-5 flex flex-wrap gap-2"><Link v-for="link in reports.links" :key="link.label" :href="link.url || ''" :class="['rounded-lg border px-3 py-2 text-sm font-semibold', link.active ? 'border-emerald-600 bg-emerald-50 text-emerald-800' : 'border-slate-300 bg-white text-slate-700', !link.url && 'pointer-events-none opacity-40']" v-html="link.label" /></nav>
    </main>
    <div v-if="reviewing" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/45 p-5 backdrop-blur-sm" @click.self="closeReview"><section role="dialog" aria-modal="true" class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-3xl border border-slate-200 bg-white p-6 shadow-2xl"><div class="flex items-start justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-wide text-red-700">{{ reasons[reviewing.reason] }}</p><h2 class="mt-1 text-xl font-semibold text-slate-950">Kullanıcı bildirimi #{{ reviewing.id }}</h2><p class="mt-2 text-sm text-slate-600">{{ $adminDate(reviewing.created_at) }}</p></div><button type="button" class="grid size-9 place-items-center rounded-lg border border-slate-300 text-slate-700" @click="closeReview">×</button></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><div class="rounded-xl bg-slate-50 p-4"><p class="text-xs font-semibold text-slate-600">Bildirilen kullanıcı</p><p class="mt-1 font-semibold text-slate-950">{{ reviewing.reported_user?.name }}</p><p class="text-sm text-slate-600">{{ reviewing.reported_user?.email }}</p><p class="mt-2 text-xs text-slate-600">{{ reviewing.reported_user?.completed_transactions || 0 }} teslimat · {{ reviewing.reported_user?.rating_count || 0 }} değerlendirme</p><Link v-if="reviewing.reported_user?.id" :href="`/admin/users/${reviewing.reported_user.id}`" class="mt-3 inline-block text-sm font-semibold text-emerald-700">Kullanıcıyı yönet</Link></div><div class="rounded-xl bg-slate-50 p-4"><p class="text-xs font-semibold text-slate-600">Bildiren</p><p class="mt-1 font-semibold text-slate-950">{{ reviewing.reporter.name }}</p><p class="text-sm text-slate-600">{{ reviewing.reporter.email }}</p></div></div><div v-if="reviewing.details" class="mt-4 rounded-xl border border-red-100 bg-red-50 p-4 text-sm leading-6 text-red-900"><strong>Bildirenin açıklaması:</strong> {{ reviewing.details }}</div><label class="mt-5 block text-sm font-semibold text-slate-800">İnceleme kararı<select v-model="decisionForm.resolution" class="mt-2 h-12 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-950"><option value="confirmed">İhlali doğrula</option><option value="dismissed">Bildirimi reddet</option><option v-if="reviewing.status !== 'pending'" value="pending">Yeniden incelemeye al</option></select></label><label v-if="decisionForm.resolution === 'confirmed'" class="mt-4 block text-sm font-semibold text-slate-800">Uygulanacak yaptırım<select v-model="decisionForm.enforcement_action" class="mt-2 h-12 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-950"><option v-for="action in enforcementActions" :key="action.value" :value="action.value">{{ action.label }}</option></select></label><p v-if="decisionForm.errors.enforcement_action" class="mt-2 text-sm font-semibold text-red-700">{{ decisionForm.errors.enforcement_action }}</p><label class="mt-4 block text-sm font-semibold text-slate-800">Yönetici notu<textarea v-model="decisionForm.note" rows="4" maxlength="1000" class="mt-2 w-full rounded-xl border border-slate-300 p-3 text-sm outline-none focus:border-emerald-600" placeholder="Seçilen işleme uygun not otomatik oluşturulur; istersen düzenleyebilirsin." /></label><p v-if="decisionForm.errors.note" class="mt-2 text-sm font-semibold text-red-700">{{ decisionForm.errors.note }}</p><button type="button" :disabled="decisionForm.processing" :class="['mt-6 h-11 w-full rounded-xl px-4 text-sm font-semibold text-white disabled:opacity-50', decisionForm.resolution === 'confirmed' ? 'bg-red-700' : 'bg-slate-950']" @click="saveDecision">Kararı kaydet</button></section></div>
  </AdminLayout>
</template>
